/// Limits `x` to the closed range `[lo, hi]`.
///
/// Returns `lo` if `x < lo`, `hi` if `x > hi`, otherwise `x`.
/// Requires `lo <= hi`.
pub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(clamp(5, 0, 10), 5);
        assert_eq!(clamp(-3, 0, 10), 0);
        assert_eq!(clamp(42, 0, 10), 10);
        assert_eq!(clamp(0, 0, 10), 0);
        assert_eq!(clamp(10, 0, 10), 10);
        assert_eq!(clamp(7, 7, 7), 7);
        assert_eq!(clamp(i64::MIN, i64::MIN, i64::MAX), i64::MIN);
        assert_eq!(clamp(i64::MAX, i64::MIN, i64::MAX), i64::MAX);
        assert_eq!(clamp(i64::MIN, 0, i64::MAX), 0);
        assert_eq!(clamp(i64::MAX, i64::MIN, 0), 0);
        assert_eq!(clamp(-1, i64::MIN, i64::MIN), i64::MIN);
        assert_eq!(clamp(1, i64::MAX, i64::MAX), i64::MAX);
    }

    proptest! {
        #[test]
        fn matches_reference(x in any::<i64>(), a in any::<i64>(), b in any::<i64>()) {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            let expected = if x < lo { lo } else if x > hi { hi } else { x };
            prop_assert_eq!(clamp(x, lo, hi), expected);
        }

        #[test]
        fn result_in_range_and_is_x_or_bound(x in any::<i64>(), a in any::<i64>(), b in any::<i64>()) {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            let r = clamp(x, lo, hi);
            prop_assert!(lo <= r && r <= hi);
            prop_assert!(r == x || r == lo || r == hi);
        }

        #[test]
        fn identity_within_range(x in any::<i64>(), a in any::<i64>(), b in any::<i64>()) {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            let v = if x < lo { lo } else if x > hi { hi } else { x };
            prop_assert_eq!(clamp(v, lo, hi), v);
        }
    }
}

/// Returns floor((a + b) / 2), computed exactly for all i64 inputs.
///
/// The sum is formed in `i128`, so it cannot overflow. Arithmetic right shift
/// by 1 on an `i128` is floor division by 2 (rounds toward negative infinity),
/// and the result always fits back into `i64`.
pub fn midpoint(a: i64, b: i64) -> i64 {
    let sum = a as i128 + b as i128;
    (sum >> 1) as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn reference(a: i64, b: i64) -> i64 {
        (a as i128 + b as i128).div_euclid(2) as i64
    }

    #[test]
    fn midpoint_fixed_examples() {
        assert_eq!(midpoint(0, 0), 0);
        assert_eq!(midpoint(1, 2), 1);
        assert_eq!(midpoint(-1, 0), -1);
        assert_eq!(midpoint(-3, -4), -4);
        assert_eq!(midpoint(-7, 0), -4);
        assert_eq!(midpoint(7, 0), 3);
        assert_eq!(midpoint(-1, 1), 0);
        assert_eq!(midpoint(i64::MAX, i64::MAX), i64::MAX);
        assert_eq!(midpoint(i64::MIN, i64::MIN), i64::MIN);
        assert_eq!(midpoint(i64::MIN, i64::MAX), -1);
        assert_eq!(midpoint(i64::MAX, i64::MIN), -1);
        assert_eq!(midpoint(i64::MAX, i64::MAX - 1), i64::MAX - 1);
        assert_eq!(midpoint(i64::MIN, i64::MIN + 1), i64::MIN);
        assert_eq!(midpoint(i64::MAX, 0), i64::MAX / 2);
        assert_eq!(midpoint(i64::MIN, 0), i64::MIN / 2);
    }

    proptest! {
        #[test]
        fn midpoint_matches_reference(a in any::<i64>(), b in any::<i64>()) {
            prop_assert_eq!(midpoint(a, b), reference(a, b));
        }

        #[test]
        fn midpoint_is_symmetric(a in any::<i64>(), b in any::<i64>()) {
            prop_assert_eq!(midpoint(a, b), midpoint(b, a));
        }

        #[test]
        fn midpoint_within_bounds(a in any::<i64>(), b in any::<i64>()) {
            let m = midpoint(a, b) as i128;
            let lo = a.min(b) as i128;
            let hi = a.max(b) as i128;
            prop_assert!(lo <= m && m <= hi);
        }
    }
}

/// Sums `a` left to right starting from 0, saturating at `i64::MAX` and
/// `i64::MIN` after every single addition.
pub fn sat_sum(a: &[i64]) -> i64 {
    let mut total: i64 = 0;
    for &x in a {
        total = total.saturating_add(x);
    }
    total
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn empty_is_zero() {
        assert_eq!(sat_sum(&[]), 0);
    }

    #[test]
    fn simple_sums() {
        assert_eq!(sat_sum(&[1, 2, 3]), 6);
        assert_eq!(sat_sum(&[-1, -2, -3]), -6);
        assert_eq!(sat_sum(&[5, -5]), 0);
    }

    #[test]
    fn saturates_high() {
        assert_eq!(sat_sum(&[i64::MAX, 1]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MAX, i64::MAX]), i64::MAX);
    }

    #[test]
    fn saturates_low() {
        assert_eq!(sat_sum(&[i64::MIN, -1]), i64::MIN);
        assert_eq!(sat_sum(&[i64::MIN, i64::MIN]), i64::MIN);
    }

    #[test]
    fn saturation_is_per_step_not_final() {
        // Saturates to MAX first, then comes back down: MAX - 1.
        assert_eq!(sat_sum(&[i64::MAX, 1, -1]), i64::MAX - 1);
        // Saturates to MIN first, then comes back up: MIN + 1.
        assert_eq!(sat_sum(&[i64::MIN, -1, 1]), i64::MIN + 1);
    }

    #[test]
    fn extremes_mixed() {
        assert_eq!(sat_sum(&[i64::MAX, i64::MIN]), -1);
        assert_eq!(sat_sum(&[i64::MIN, i64::MAX]), -1);
    }

    proptest! {
        #[test]
        fn matches_reference(v in proptest::collection::vec(any::<i64>(), 0..64)) {
            // Reference: exact per-step clamping in i128.
            let mut total: i128 = 0;
            for &x in &v {
                total = (total + x as i128).clamp(i64::MIN as i128, i64::MAX as i128);
            }
            prop_assert_eq!(sat_sum(&v), total as i64);
        }
    }
}

/// Returns how many elements `x` of `a` satisfy `lo <= x <= hi`.
///
/// Both ends are inclusive. If `lo > hi`, the result is `0`.
pub fn count_in_range(a: &[i64], lo: i64, hi: i64) -> usize {
    if lo > hi {
        return 0;
    }
    a.iter().filter(|&&x| lo <= x && x <= hi).count()
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn naive(a: &[i64], lo: i64, hi: i64) -> usize {
        let mut c = 0usize;
        for &x in a {
            if lo <= x && x <= hi {
                c += 1;
            }
        }
        c
    }

    #[test]
    fn examples() {
        assert_eq!(count_in_range(&[], 0, 10), 0);
        assert_eq!(count_in_range(&[1, 2, 3, 4, 5], 2, 4), 3);
        assert_eq!(count_in_range(&[1, 2, 3, 4, 5], 4, 2), 0);
        assert_eq!(count_in_range(&[5, 5, 5], 5, 5), 3);
        assert_eq!(count_in_range(&[1, 2, 3], 10, 20), 0);
        assert_eq!(count_in_range(&[i64::MIN, 0, i64::MAX], i64::MIN, i64::MAX), 3);
        assert_eq!(count_in_range(&[i64::MIN, i64::MAX], i64::MAX, i64::MIN), 0);
        assert_eq!(count_in_range(&[-3, -1, 0, 2], -3, -1), 2);
    }

    proptest! {
        #[test]
        fn matches_naive(
            a in proptest::collection::vec(any::<i64>(), 0..64),
            lo in any::<i64>(),
            hi in any::<i64>(),
        ) {
            prop_assert_eq!(count_in_range(&a, lo, hi), naive(&a, lo, hi));
        }

        #[test]
        fn matches_naive_small(
            a in proptest::collection::vec(-5i64..5, 0..64),
            lo in -6i64..6,
            hi in -6i64..6,
        ) {
            prop_assert_eq!(count_in_range(&a, lo, hi), naive(&a, lo, hi));
        }
    }
}

/// Returns the smallest index `i` such that `a[i]` is a largest element of `a`.
///
/// For a non-empty slice this is the position of the first occurrence of the
/// maximum value. (For an empty slice, `0` is returned.)
pub fn first_max_index(a: &[i64]) -> usize {
    let mut best_idx: usize = 0;
    let mut best_val: i64 = match a.first() {
        Some(&v) => v,
        None => return 0,
    };
    for (i, &v) in a.iter().enumerate().skip(1) {
        if v > best_val {
            best_val = v;
            best_idx = i;
        }
    }
    best_idx
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn single_element() {
        assert_eq!(first_max_index(&[42]), 0);
        assert_eq!(first_max_index(&[i64::MIN]), 0);
    }

    #[test]
    fn basic_cases() {
        assert_eq!(first_max_index(&[1, 3, 2]), 1);
        assert_eq!(first_max_index(&[5, 1, 2]), 0);
        assert_eq!(first_max_index(&[1, 2, 3]), 2);
    }

    #[test]
    fn ties_return_first() {
        assert_eq!(first_max_index(&[7, 7, 7]), 0);
        assert_eq!(first_max_index(&[1, 9, 3, 9, 9]), 1);
        assert_eq!(first_max_index(&[-1, -5, -1]), 0);
    }

    #[test]
    fn extremes() {
        assert_eq!(first_max_index(&[i64::MIN, i64::MAX, i64::MAX]), 1);
        assert_eq!(first_max_index(&[i64::MIN, i64::MIN]), 0);
        assert_eq!(first_max_index(&[i64::MAX, i64::MIN]), 0);
    }

    proptest! {
        #[test]
        fn matches_reference(a in proptest::collection::vec(any::<i64>(), 1..64)) {
            let max = *a.iter().max().unwrap();
            let expected = a.iter().position(|&x| x == max).unwrap();
            prop_assert_eq!(first_max_index(&a), expected);
        }

        #[test]
        fn small_range_ties(a in proptest::collection::vec(-3i64..3, 1..64)) {
            let max = *a.iter().max().unwrap();
            let expected = a.iter().position(|&x| x == max).unwrap();
            let idx = first_max_index(&a);
            prop_assert_eq!(idx, expected);
            prop_assert_eq!(a[idx], max);
        }
    }
}

/// Returns the largest index `i` such that `a[i]` is a smallest element of `a`.
///
/// # Panics
/// Panics if `a` is empty (outside the stated input domain).
pub fn last_min_index(a: &[i64]) -> usize {
    assert!(!a.is_empty(), "last_min_index: slice must be non-empty");
    let mut best = 0usize;
    for (i, &x) in a.iter().enumerate().skip(1) {
        // `<=` so that later equal minima replace earlier ones.
        if x <= a[best] {
            best = i;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(last_min_index(&[5]), 0);
        assert_eq!(last_min_index(&[1, 2, 3]), 0);
        assert_eq!(last_min_index(&[3, 2, 1]), 2);
        assert_eq!(last_min_index(&[2, 1, 1, 3]), 2);
        assert_eq!(last_min_index(&[1, 1, 1]), 2);
        assert_eq!(last_min_index(&[4, -1, 7, -1, 0]), 3);
        assert_eq!(last_min_index(&[i64::MAX, i64::MIN, i64::MIN]), 2);
        assert_eq!(last_min_index(&[i64::MIN, i64::MAX]), 0);
    }

    fn reference(a: &[i64]) -> usize {
        let m = *a.iter().min().unwrap();
        (0..a.len()).filter(|&i| a[i] == m).last().unwrap()
    }

    proptest! {
        #[test]
        fn matches_reference(a in proptest::collection::vec(-5i64..5, 1..50)) {
            prop_assert_eq!(last_min_index(&a), reference(&a));
        }

        #[test]
        fn matches_reference_wide(a in proptest::collection::vec(any::<i64>(), 1..50)) {
            let i = last_min_index(&a);
            prop_assert_eq!(i, reference(&a));
            prop_assert!(a[i] == *a.iter().min().unwrap());
        }
    }
}

/// Returns `true` exactly when every element of `a` is strictly smaller than
/// the element that follows it, i.e. `a[i] < a[i + 1]` for every valid `i`.
///
/// Empty and one-element slices are strictly increasing.
pub fn strictly_increasing(a: &[i64]) -> bool {
    a.windows(2).all(|w| w[0] < w[1])
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert!(strictly_increasing(&[]));
        assert!(strictly_increasing(&[5]));
        assert!(strictly_increasing(&[1, 2]));
        assert!(strictly_increasing(&[-3, -2, 0, 7, 100]));
        assert!(strictly_increasing(&[i64::MIN, 0, i64::MAX]));
        assert!(!strictly_increasing(&[1, 1]));
        assert!(!strictly_increasing(&[1, 3, 2]));
        assert!(!strictly_increasing(&[2, 1]));
        assert!(!strictly_increasing(&[1, 2, 2, 3]));
        assert!(!strictly_increasing(&[i64::MAX, i64::MIN]));
    }

    proptest! {
        #[test]
        fn matches_reference(a in proptest::collection::vec(any::<i64>(), 0..50)) {
            let expected = a.iter().zip(a.iter().skip(1)).all(|(x, y)| x < y);
            prop_assert_eq!(strictly_increasing(&a), expected);
        }

        #[test]
        fn sorted_dedup_is_strictly_increasing(mut a in proptest::collection::vec(any::<i64>(), 0..50)) {
            a.sort();
            a.dedup();
            prop_assert!(strictly_increasing(&a));
        }
    }
}

/// Returns the smallest index `i` such that `a[i] >= t`, or `a.len()` if every
/// element of `a` is smaller than `t`.
///
/// `a` must be sorted in non-decreasing order. Runs in O(log n) time using
/// binary search.
pub fn lower_bound(a: &[i64], t: i64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = a.len();
    // Invariant: all elements before `lo` are < t, and all elements at or
    // after `hi` are >= t. The answer lies in [lo, hi].
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < t {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn reference(a: &[i64], t: i64) -> usize {
        a.iter().position(|&x| x >= t).unwrap_or(a.len())
    }

    #[test]
    fn empty_slice() {
        assert_eq!(lower_bound(&[], 0), 0);
        assert_eq!(lower_bound(&[], i64::MIN), 0);
        assert_eq!(lower_bound(&[], i64::MAX), 0);
    }

    #[test]
    fn single_element() {
        assert_eq!(lower_bound(&[5], 4), 0);
        assert_eq!(lower_bound(&[5], 5), 0);
        assert_eq!(lower_bound(&[5], 6), 1);
    }

    #[test]
    fn duplicates_return_first() {
        let a = [1, 2, 2, 2, 2, 3];
        assert_eq!(lower_bound(&a, 2), 1);
        assert_eq!(lower_bound(&a, 1), 0);
        assert_eq!(lower_bound(&a, 3), 5);
        assert_eq!(lower_bound(&a, 4), 6);
        assert_eq!(lower_bound(&a, 0), 0);
    }

    #[test]
    fn all_equal() {
        let a = [7; 10];
        assert_eq!(lower_bound(&a, 7), 0);
        assert_eq!(lower_bound(&a, 6), 0);
        assert_eq!(lower_bound(&a, 8), 10);
    }

    #[test]
    fn extreme_values() {
        let a = [i64::MIN, i64::MIN, 0, i64::MAX, i64::MAX];
        assert_eq!(lower_bound(&a, i64::MIN), 0);
        assert_eq!(lower_bound(&a, -1), 2);
        assert_eq!(lower_bound(&a, 0), 2);
        assert_eq!(lower_bound(&a, 1), 3);
        assert_eq!(lower_bound(&a, i64::MAX), 3);
        let b = [i64::MIN, i64::MAX];
        assert_eq!(lower_bound(&b, i64::MAX), 1);
        assert_eq!(lower_bound(&b, i64::MIN), 0);
    }

    proptest! {
        #[test]
        fn matches_reference(mut a in proptest::collection::vec(any::<i64>(), 0..200), t in any::<i64>()) {
            a.sort_unstable();
            prop_assert_eq!(lower_bound(&a, t), reference(&a, t));
        }

        #[test]
        fn small_range_matches_reference(mut a in proptest::collection::vec(-5i64..=5, 0..64), t in -6i64..=6) {
            a.sort_unstable();
            let i = lower_bound(&a, t);
            prop_assert_eq!(i, reference(&a, t));
            prop_assert!(i <= a.len());
            if i < a.len() { prop_assert!(a[i] >= t); }
            if i > 0 { prop_assert!(a[i - 1] < t); }
        }
    }
}

/// Floor division: `a / b` rounded toward negative infinity.
///
/// Rust's `/` truncates toward zero, so the result is adjusted down by one
/// when the division is inexact and the operands have opposite signs.
///
/// Requires `b != 0` and not (`a == i64::MIN` && `b == -1`).
pub fn div_floor(a: i64, b: i64) -> i64 {
    let q = a / b;
    let r = a % b;
    if r != 0 && ((r < 0) != (b < 0)) {
        q - 1
    } else {
        q
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(div_floor(7, 2), 3);
        assert_eq!(div_floor(-7, 2), -4);
        assert_eq!(div_floor(7, -2), -4);
        assert_eq!(div_floor(-7, -2), 3);
        assert_eq!(div_floor(6, 2), 3);
        assert_eq!(div_floor(-6, 2), -3);
        assert_eq!(div_floor(6, -2), -3);
        assert_eq!(div_floor(-6, -2), 3);
        assert_eq!(div_floor(0, 5), 0);
        assert_eq!(div_floor(0, -5), 0);
        assert_eq!(div_floor(1, i64::MAX), 0);
        assert_eq!(div_floor(-1, i64::MAX), -1);
        assert_eq!(div_floor(-1, i64::MIN), 0);
        assert_eq!(div_floor(1, i64::MIN), -1);
        assert_eq!(div_floor(i64::MIN, 1), i64::MIN);
        assert_eq!(div_floor(i64::MIN, -2), 1i64 << 62);
        assert_eq!(div_floor(i64::MAX, -1), -i64::MAX);
        assert_eq!(div_floor(i64::MIN, i64::MAX), -2);
        assert_eq!(div_floor(i64::MIN + 1, -1), i64::MAX);
    }

    // Independent reference using i128 and Euclidean division.
    fn reference(a: i64, b: i64) -> i64 {
        let a = a as i128;
        let b = b as i128;
        // div_euclid: a = q*b + r with 0 <= r < |b|.
        let q = a.div_euclid(b);
        let r = a.rem_euclid(b);
        // For b > 0, q is already the floor.
        // For b < 0, a/b = q + r/b with r/b in (-1, 0], so floor is q - 1 when r != 0.
        let f = if b < 0 && r != 0 { q - 1 } else { q };
        f as i64
    }

    proptest! {
        #[test]
        fn matches_reference(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0);
            prop_assume!(!(a == i64::MIN && b == -1));
            prop_assert_eq!(div_floor(a, b), reference(a, b));
        }

        #[test]
        fn floor_bounds(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0);
            prop_assume!(!(a == i64::MIN && b == -1));
            let q = div_floor(a, b) as i128;
            let a = a as i128;
            let b = b as i128;
            // q*b <= a < (q+1)*b when b > 0; reversed when b < 0.
            if b > 0 {
                prop_assert!(q * b <= a && a < (q + 1) * b);
            } else {
                prop_assert!((q + 1) * b < a && a <= q * b);
            }
        }

        #[test]
        fn small_values(a in -1000i64..1000, b in -1000i64..1000) {
            prop_assume!(b != 0);
            let expected = (a as f64 / b as f64).floor() as i64;
            prop_assert_eq!(div_floor(a, b), expected);
        }
    }
}

/// Returns `a - b * floor(a / b)`: the remainder of floor division.
///
/// The result is either 0 or has the same sign as `b`, and its absolute
/// value is smaller than `|b|`.
///
/// Computed in `i128` so that no intermediate value overflows, including
/// `mod_floor(i64::MIN, -1)` (which is 0).
///
/// # Panics
/// Panics if `b == 0`.
pub fn mod_floor(a: i64, b: i64) -> i64 {
    let a = a as i128;
    let b = b as i128;
    // Truncated remainder: sign follows `a`. `b != 0` is required.
    let r = a % b;
    // Adjust to floor semantics: if the remainder is nonzero and its sign
    // differs from `b`'s, shift it by `b`. The result then lies in
    // (-|b|, |b|) with the sign of `b`, so it always fits in i64.
    let r = if r != 0 && ((r < 0) != (b < 0)) { r + b } else { r };
    r as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(mod_floor(7, 3), 1);
        assert_eq!(mod_floor(-7, 3), 2);
        assert_eq!(mod_floor(7, -3), -2);
        assert_eq!(mod_floor(-7, -3), -1);
        assert_eq!(mod_floor(0, 5), 0);
        assert_eq!(mod_floor(0, -5), 0);
        assert_eq!(mod_floor(6, 3), 0);
        assert_eq!(mod_floor(-6, 3), 0);
        assert_eq!(mod_floor(6, -3), 0);
        assert_eq!(mod_floor(-6, -3), 0);
        assert_eq!(mod_floor(i64::MIN, -1), 0);
        assert_eq!(mod_floor(i64::MAX, -1), 0);
        assert_eq!(mod_floor(i64::MIN, i64::MAX), i64::MAX - 1);
        // floor(MAX / MIN) = -1, so MAX - (-1) * MIN = MAX + MIN = -1.
        assert_eq!(mod_floor(i64::MAX, i64::MIN), -1);
        assert_eq!(mod_floor(i64::MIN, i64::MIN), 0);
        assert_eq!(mod_floor(i64::MIN, 1), 0);
        assert_eq!(mod_floor(i64::MAX, i64::MAX), 0);
        assert_eq!(mod_floor(-1, i64::MAX), i64::MAX - 1);
        assert_eq!(mod_floor(1, i64::MIN), i64::MIN + 1);
    }

    fn reference(a: i64, b: i64) -> i64 {
        // Exact floor division in i128, then a - b * floor(a / b).
        let a = a as i128;
        let b = b as i128;
        let mut q = a / b;
        if (a % b != 0) && ((a < 0) != (b < 0)) {
            q -= 1;
        }
        (a - b * q) as i64
    }

    fn nonzero() -> impl Strategy<Value = i64> {
        any::<i64>().prop_filter("nonzero", |b| *b != 0)
    }

    proptest! {
        #[test]
        fn matches_reference(a in any::<i64>(), b in nonzero()) {
            prop_assert_eq!(mod_floor(a, b), reference(a, b));
        }

        #[test]
        fn sign_and_bound(a in any::<i64>(), b in nonzero()) {
            let r = mod_floor(a, b);
            prop_assert!(r == 0 || ((r < 0) == (b < 0)));
            prop_assert!((r as i128).abs() < (b as i128).abs());
            // a - r must be an exact multiple of b.
            prop_assert_eq!(((a as i128) - (r as i128)) % (b as i128), 0);
        }

        #[test]
        fn small_values(a in -100i64..100, b in prop_oneof![-100i64..-1, 1i64..100]) {
            // For small magnitudes, f64 floor division is exact.
            let q = ((a as f64) / (b as f64)).floor() as i64;
            prop_assert_eq!(mod_floor(a, b), a - b * q);
        }
    }
}

/// Returns the largest sum of a non-empty contiguous run `a[i..=j]` (i <= j).
///
/// Uses Kadane's algorithm in O(n) time and O(1) extra space.
/// All sums fit in `i64` for the stated domain (|a[k]| <= 1e9, len <= 1e6,
/// so |sum| <= 1e15).
///
/// # Panics
/// Panics if `a` is empty (outside the stated input domain).
pub fn max_subarray(a: &[i64]) -> i64 {
    assert!(!a.is_empty(), "max_subarray: input must be non-empty");
    let mut best = a[0];
    let mut cur = a[0];
    for &x in &a[1..] {
        // Either extend the current run or start a new one at x.
        cur = if cur > 0 { cur + x } else { x };
        if cur > best {
            best = cur;
        }
    }
    best
}

