/// Rotates `a` to the right by `k` positions in place: the element at index `i`
/// moves to index `(i + k) mod a.len()`. `k` may exceed `a.len()`. An empty
/// slice stays empty.
pub fn rotate_right(a: &mut [i64], k: usize) {
    let n = a.len();
    if n == 0 {
        return;
    }
    a.rotate_right(k % n);
}

