/// Deduplicates a sorted (non-decreasing) slice in place.
///
/// The distinct values of `a` are moved to the front in increasing order,
/// every remaining position is set to `0`, and the number of distinct values
/// is returned.
pub fn dedup_sorted(a: &mut [i64]) -> usize {
    let n = a.len();
    if n == 0 {
        return 0;
    }
    // `w` is the number of distinct values written so far; `a[w - 1]` is the
    // most recently written distinct value.
    let mut w = 1;
    for r in 1..n {
        let v = a[r];
        if v != a[w - 1] {
            a[w] = v;
            w += 1;
        }
    }
    for x in a[w..].iter_mut() {
        *x = 0;
    }
    w
}

