/// Moves every zero element of `a` to the end of the slice, in place,
/// keeping the relative order of the non-zero elements.
///
/// Runs in O(n) time and O(1) extra space.
pub fn move_zeros(a: &mut [i64]) {
    // Invariant: a[..w] holds the non-zero elements seen so far, in their
    // original order; a[w..i] holds zeros.
    let mut w = 0;
    for i in 0..a.len() {
        if a[i] != 0 {
            a.swap(w, i);
            w += 1;
        }
    }
}

