/// Greatest common divisor of `|a|` and `|b|`.
///
/// Always non-negative. `gcd(0, 0) == 0` and `gcd(a, 0) == |a|`.
/// Inputs are `> i64::MIN`, so `|a|` and `|b|` fit in `i64`. The arithmetic is
/// done on `u64` (via `unsigned_abs`) so no intermediate step can overflow.
pub fn gcd(a: i64, b: i64) -> i64 {
    let mut x = a.unsigned_abs();
    let mut y = b.unsigned_abs();
    while y != 0 {
        let r = x % y;
        x = y;
        y = r;
    }
    // The gcd is at most max(|a|, |b|) <= i64::MAX, so this conversion is exact.
    x as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(gcd(0, 0), 0);
        assert_eq!(gcd(0, 5), 5);
        assert_eq!(gcd(5, 0), 5);
        assert_eq!(gcd(0, -7), 7);
        assert_eq!(gcd(-7, 0), 7);
        assert_eq!(gcd(12, 18), 6);
        assert_eq!(gcd(-12, 18), 6);
        assert_eq!(gcd(12, -18), 6);
        assert_eq!(gcd(-12, -18), 6);
        assert_eq!(gcd(1, 1), 1);
        assert_eq!(gcd(-1, 1), 1);
        assert_eq!(gcd(17, 13), 1);
    }

    #[test]
    fn extremes() {
        let max = i64::MAX;
        let min1 = i64::MIN + 1; // |min1| == i64::MAX
        assert_eq!(gcd(max, max), max);
        assert_eq!(gcd(min1, min1), max);
        assert_eq!(gcd(min1, 0), max);
        assert_eq!(gcd(0, min1), max);
        assert_eq!(gcd(max, min1), max);
        assert_eq!(gcd(max, -max), max);
        assert_eq!(gcd(min1, 1), 1);
        assert_eq!(gcd(max, 1), 1);
        assert_eq!(gcd(max, max - 1), 1); // consecutive integers are coprime
        assert_eq!(gcd(1 << 62, 1 << 40), 1 << 40);
    }

    fn reference_gcd(a: i64, b: i64) -> i64 {
        // Independent reference computed in i128.
        let mut x = (a as i128).abs();
        let mut y = (b as i128).abs();
        while y != 0 {
            let t = x % y;
            x = y;
            y = t;
        }
        x as i64
    }

    proptest! {
        #[test]
        fn matches_reference(a in (i64::MIN + 1)..=i64::MAX, b in (i64::MIN + 1)..=i64::MAX) {
            prop_assert_eq!(gcd(a, b), reference_gcd(a, b));
        }

        #[test]
        fn nonnegative_and_divides_both(a in (i64::MIN + 1)..=i64::MAX, b in (i64::MIN + 1)..=i64::MAX) {
            let g = gcd(a, b);
            prop_assert!(g >= 0);
            if g != 0 {
                prop_assert_eq!(a % g, 0);
                prop_assert_eq!(b % g, 0);
            } else {
                prop_assert_eq!(a, 0);
                prop_assert_eq!(b, 0);
            }
        }

        #[test]
        fn symmetric(a in (i64::MIN + 1)..=i64::MAX, b in (i64::MIN + 1)..=i64::MAX) {
            prop_assert_eq!(gcd(a, b), gcd(b, a));
            prop_assert_eq!(gcd(a, b), gcd(-a, b));
            prop_assert_eq!(gcd(a, b), gcd(a, -b));
        }

        #[test]
        fn zero_cases(a in (i64::MIN + 1)..=i64::MAX) {
            prop_assert_eq!(gcd(a, 0), a.abs());
            prop_assert_eq!(gcd(0, a), a.abs());
        }

        #[test]
        fn small_values(a in -1000i64..=1000, b in -1000i64..=1000) {
            prop_assert_eq!(gcd(a, b), reference_gcd(a, b));
        }
    }
}

/// Returns the integer square root of `n`: the largest `r >= 0` with `r * r <= n`.
///
/// Intended for `n >= 0`. A negative input is a precondition violation and panics.
pub fn isqrt(n: i64) -> i64 {
    assert!(n >= 0, "isqrt: negative input {}", n);
    let n = n as u64;
    // Floating-point estimate, then correct it exactly using wide integers.
    let mut r = (n as f64).sqrt() as u64;
    while (r as u128) * (r as u128) > n as u128 {
        r -= 1;
    }
    while ((r + 1) as u128) * ((r + 1) as u128) <= n as u128 {
        r += 1;
    }
    r as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    const MAX_ROOT: i64 = 3_037_000_499;

    fn check(n: i64) {
        let r = isqrt(n);
        assert!(r >= 0);
        assert!((r as i128) * (r as i128) <= n as i128, "r*r > n for n={}", n);
        assert!(
            ((r as i128) + 1) * ((r as i128) + 1) > n as i128,
            "(r+1)^2 <= n for n={}",
            n
        );
    }

    #[test]
    fn small_values() {
        let expected = [0i64, 1, 1, 1, 2, 2, 2, 2, 2, 3, 3];
        for (n, &e) in expected.iter().enumerate() {
            assert_eq!(isqrt(n as i64), e, "n={}", n);
        }
    }

    #[test]
    fn perfect_squares_and_neighbours() {
        for r in 0..=2_000_000i64 {
            let sq = r * r;
            assert_eq!(isqrt(sq), r);
            if sq > 0 {
                assert_eq!(isqrt(sq - 1), r - 1);
            }
            assert_eq!(isqrt(sq + 2 * r), r); // (r+1)^2 - 1
            assert_eq!(isqrt(sq + 2 * r + 1), r + 1);
        }
    }

    #[test]
    fn extremes() {
        assert_eq!(isqrt(0), 0);
        assert_eq!(isqrt(i64::MAX), MAX_ROOT);
        assert_eq!(isqrt(i64::MAX - 1), MAX_ROOT);
        assert_eq!(isqrt(MAX_ROOT * MAX_ROOT), MAX_ROOT);
        assert_eq!(isqrt(MAX_ROOT * MAX_ROOT - 1), MAX_ROOT - 1);
        // (MAX_ROOT + 1)^2 exceeds i64::MAX, so the root stays at MAX_ROOT.
        assert!((MAX_ROOT as i128 + 1).pow(2) > i64::MAX as i128);
        check(i64::MAX);
    }

    #[test]
    #[should_panic]
    fn negative_panics() {
        isqrt(-1);
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(20_000))]

        #[test]
        fn matches_definition(n in 0i64..=i64::MAX) {
            check(n);
        }

        #[test]
        fn monotone(a in 0i64..=i64::MAX, b in 0i64..=i64::MAX) {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            prop_assert!(isqrt(lo) <= isqrt(hi));
        }
    }
}

/// Returns the number of decimal digits of `|n|`. The sign is not counted,
/// and 0 has one digit.
///
/// Uses `unsigned_abs` so that `i64::MIN` (whose absolute value does not fit
/// in an `i64`) is handled without overflow.
pub fn count_digits(n: i64) -> i64 {
    let mut m: u64 = n.unsigned_abs();
    let mut count: i64 = 1;
    while m >= 10 {
        m /= 10;
        count += 1;
    }
    count
}

#[cfg(test)]
mod tests {
