        assert_eq!(count_digits(-1), 1);
        assert_eq!(count_digits(9), 1);
        assert_eq!(count_digits(10), 2);
        assert_eq!(count_digits(-10), 2);
        assert_eq!(count_digits(99), 2);
        assert_eq!(count_digits(100), 3);
        assert_eq!(count_digits(-999), 3);
        assert_eq!(count_digits(1000), 4);
        assert_eq!(count_digits(i64::MAX), 19);
        assert_eq!(count_digits(i64::MIN), 19);
        assert_eq!(count_digits(i64::MIN + 1), 19);
        assert_eq!(count_digits(1_000_000_000_000_000_000), 19);
        assert_eq!(count_digits(999_999_999_999_999_999), 18);
    }

    fn reference(n: i64) -> i64 {
        (n.unsigned_abs().to_string().len()) as i64
    }

    proptest! {
        #[test]
        fn matches_string_length(n in any::<i64>()) {
            prop_assert_eq!(count_digits(n), reference(n));
        }

        #[test]
        fn small_values(n in -1_000_000i64..=1_000_000i64) {
            prop_assert_eq!(count_digits(n), reference(n));
        }

        #[test]
        fn power_of_ten_boundaries(e in 0u32..19u32, d in -2i64..=2i64) {
            let p = 10i64.pow(e);
            let n = p.saturating_add(d);
            prop_assert_eq!(count_digits(n), reference(n));
            prop_assert_eq!(count_digits(-n), reference(-n));
        }
    }
}

/// Returns `a[i] + a[i + 1] + ... + a[j - 1]`, the sum over the half-open
/// range `[i, j)` of `a`. Returns 0 when `i == j`.
///
/// Domain: `i <= j <= a.len()`, `a.len() <= 1_000_000`, and every element lies
/// in `[-1_000_000_000_000, 1_000_000_000_000]`. The total magnitude is at most
/// `10^18`, which fits in `i64`.
pub fn range_sum(a: &[i64], i: usize, j: usize) -> i64 {
    if i >= j {
        return 0;
    }
    a[i..j].iter().sum()
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn empty_range_is_zero() {
        let a = [1i64, 2, 3];
        assert_eq!(range_sum(&a, 0, 0), 0);
        assert_eq!(range_sum(&a, 2, 2), 0);
        assert_eq!(range_sum(&a, 3, 3), 0);
        assert_eq!(range_sum(&[], 0, 0), 0);
    }

    #[test]
    fn basic_ranges() {
        let a = [5i64, -3, 10, 7, -1];
        assert_eq!(range_sum(&a, 0, 5), 18);
        assert_eq!(range_sum(&a, 0, 1), 5);
        assert_eq!(range_sum(&a, 1, 3), 7);
        assert_eq!(range_sum(&a, 4, 5), -1);
        assert_eq!(range_sum(&a, 2, 4), 17);
    }

    #[test]
    fn extreme_values() {
        let m = 1_000_000_000_000i64;
        let a = vec![m; 1_000_000];
        assert_eq!(range_sum(&a, 0, 1_000_000), 1_000_000 * m);
        let b = vec![-m; 1_000_000];
        assert_eq!(range_sum(&b, 0, 1_000_000), -1_000_000 * m);
    }

    fn naive(a: &[i64], i: usize, j: usize) -> i64 {
        let mut s = 0i64;
        for k in i..j {
            s += a[k];
        }
        s
    }

    proptest! {
        #[test]
        fn matches_naive(
            a in proptest::collection::vec(-1_000_000_000_000i64..=1_000_000_000_000i64, 0..200),
            x in 0usize..200,
            y in 0usize..200,
        ) {
            let n = a.len();
            let i = x.min(n);
            let j = y.min(n);
            let (i, j) = if i <= j { (i, j) } else { (j, i) };
            prop_assert_eq!(range_sum(&a, i, j), naive(&a, i, j));
        }
    }
}

/// Returns the value that occurs strictly more than `a.len() / 2` times in `a`,
/// or `i64::MIN` if no such value exists (including when `a` is empty).
pub fn majority(a: &[i64]) -> i64 {
    if a.is_empty() {
        return i64::MIN;
    }

    // Boyer-Moore voting: the only possible strict majority is the surviving candidate.
    let mut candidate: i64 = 0;
    let mut count: usize = 0;
    for &x in a {
        if count == 0 {
            candidate = x;
            count = 1;
        } else if x == candidate {
            count += 1;
        } else {
            count -= 1;
        }
    }

    // Verify the candidate actually occurs more than len / 2 times.
    let occurrences = a.iter().filter(|&&x| x == candidate).count();
    if occurrences > a.len() / 2 {
        candidate
    } else {
        i64::MIN
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn naive(a: &[i64]) -> i64 {
        let n = a.len();
        for &v in a {
            let c = a.iter().filter(|&&x| x == v).count();
            if c > n / 2 {
                return v;
            }
        }
        i64::MIN
    }

    #[test]
    fn empty() {
        assert_eq!(majority(&[]), i64::MIN);
    }

    #[test]
    fn single() {
        assert_eq!(majority(&[5]), 5);
        assert_eq!(majority(&[i64::MIN]), i64::MIN);
        assert_eq!(majority(&[i64::MAX]), i64::MAX);
    }

    #[test]
    fn two_elements() {
        assert_eq!(majority(&[1, 1]), 1);
        assert_eq!(majority(&[1, 2]), i64::MIN);
    }

    #[test]
    fn basic_cases() {
        assert_eq!(majority(&[3, 3, 4, 2, 3]), 3);
        assert_eq!(majority(&[3, 3, 4, 2]), i64::MIN); // exactly half is not enough
        assert_eq!(majority(&[1, 2, 3]), i64::MIN);
        assert_eq!(majority(&[2, 2, 1, 1, 2]), 2);
        assert_eq!(majority(&[-7, -7, -7, 0, 9]), -7);
        assert_eq!(majority(&[i64::MAX, i64::MAX, 0]), i64::MAX);
        assert_eq!(majority(&[i64::MIN, 0, i64::MIN, 1, i64::MIN]), i64::MIN);
    }

    #[test]
    fn majority_at_end_after_noise() {
        assert_eq!(majority(&[1, 2, 3, 4, 5, 9, 9, 9, 9, 9, 9]), 9);
        assert_eq!(majority(&[9, 9, 9, 9, 9, 9, 1, 2, 3, 4, 5]), 9);
        // 5 of 10 is exactly half: not a strict majority.
        assert_eq!(majority(&[1, 2, 3, 4, 5, 9, 9, 9, 9, 9]), i64::MIN);
    }

    proptest! {
        #[test]
        fn matches_naive(a in proptest::collection::vec(-5i64..5, 0..40)) {
            prop_assert_eq!(majority(&a), naive(&a));
        }

        #[test]
        fn planted_majority_is_found(
            v in any::<i64>(),
            noise in proptest::collection::vec(any::<i64>(), 0..30),
            extra in 1usize..10,
        ) {
            let mut a: Vec<i64> = noise.clone();
            // Strict majority requires more copies of v than all other elements combined.
            for _ in 0..(noise.len() + extra) { a.push(v); }
            a.reverse();
            let got = majority(&a);
            prop_assert_eq!(got, v);
            prop_assert_eq!(got, naive(&a));
        }

        #[test]
        fn any_values(a in proptest::collection::vec(any::<i64>(), 0..40)) {
            prop_assert_eq!(majority(&a), naive(&a));
        }
    }
}

/// Returns the length of the longest run of consecutive equal elements in `a`.
///
/// Returns 0 for an empty slice and 1 when no two neighbours are equal.
pub fn longest_run(a: &[i64]) -> usize {
    let mut best: usize = 0;
    let mut cur: usize = 0;
    let mut prev: Option<i64> = None;
    for &x in a {
        if prev == Some(x) {
            cur += 1;
        } else {
            cur = 1;
            prev = Some(x);
        }
        if cur > best {
            best = cur;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn reference(a: &[i64]) -> usize {
        let mut best = 0usize;
        for i in 0..a.len() {
            let mut j = i;
            while j < a.len() && a[j] == a[i] {
                j += 1;
            }
            best = best.max(j - i);
        }
        best
    }

    #[test]
    fn examples() {
        assert_eq!(longest_run(&[]), 0);
        assert_eq!(longest_run(&[5]), 1);
        assert_eq!(longest_run(&[1, 2, 3]), 1);
        assert_eq!(longest_run(&[1, 1, 2, 2, 2, 3]), 3);
        assert_eq!(longest_run(&[7, 7, 7, 7]), 4);
        assert_eq!(longest_run(&[1, 2, 2, 1, 1, 1, 2]), 3);
        assert_eq!(longest_run(&[i64::MIN, i64::MIN, i64::MAX]), 2);
        assert_eq!(longest_run(&[-1, -1, 1, 1, 1, -1]), 3);
    }

    proptest! {
        #[test]
        fn matches_reference(a in proptest::collection::vec(-3i64..3, 0..200)) {
            prop_assert_eq!(longest_run(&a), reference(&a));
        }

        #[test]
        fn bounded_by_length(a in proptest::collection::vec(any::<i64>(), 0..200)) {
            let r = longest_run(&a);
            prop_assert!(r <= a.len());
            if a.is_empty() {
                prop_assert_eq!(r, 0);
            } else {
                prop_assert!(r >= 1);
            }
        }
    }
}

/// Merges two non-decreasing slices into `out`, overwriting its previous contents.
///
/// `out` must have length `a.len() + b.len()`. After the call, `out` holds every
/// element of `a` and `b` in non-decreasing order. Runs in O(a.len() + b.len())
/// time and performs no allocation.
pub fn merge_sorted(a: &[i64], b: &[i64], out: &mut [i64]) {
    let (mut i, mut j) = (0usize, 0usize);
    for slot in out.iter_mut() {
        let take_a = match (a.get(i), b.get(j)) {
            (Some(x), Some(y)) => x <= y,
            (Some(_), None) => true,
            (None, Some(_)) => false,
            (None, None) => break,
        };
        if take_a {
            *slot = a[i];
            i += 1;
        } else {
            *slot = b[j];
            j += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn run(a: &[i64], b: &[i64]) -> Vec<i64> {
        let mut out = vec![0i64; a.len() + b.len()];
        merge_sorted(a, b, &mut out);
        out
    }

    fn sorted_concat(a: &[i64], b: &[i64]) -> Vec<i64> {
        let mut v: Vec<i64> = a.iter().chain(b.iter()).copied().collect();
        v.sort();
        v
    }

    #[test]
    fn empty_cases() {
        assert_eq!(run(&[], &[]), Vec::<i64>::new());
        assert_eq!(run(&[], &[1, 2, 3]), vec![1, 2, 3]);
        assert_eq!(run(&[1, 2, 3], &[]), vec![1, 2, 3]);
    }

    #[test]
    fn basic_cases() {
        assert_eq!(run(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
        assert_eq!(run(&[1, 2], &[3, 4]), vec![1, 2, 3, 4]);
        assert_eq!(run(&[3, 4], &[1, 2]), vec![1, 2, 3, 4]);
        assert_eq!(run(&[2, 2, 2], &[2, 2]), vec![2, 2, 2, 2, 2]);
    }

    #[test]
    fn extreme_values() {
        assert_eq!(
            run(&[i64::MIN, 0, i64::MAX], &[i64::MIN, -1, i64::MAX]),
            vec![i64::MIN, i64::MIN, -1, 0, i64::MAX, i64::MAX]
        );
    }

    #[test]
    fn overwrites_garbage() {
        let mut out = [i64::MAX, i64::MIN, 42, -42];
        merge_sorted(&[-5, 7], &[0, 100], &mut out);
        assert_eq!(out, [-5, 0, 7, 100]);
    }

    proptest! {
        #[test]
        fn matches_reference(
            mut a in proptest::collection::vec(any::<i64>(), 0..64),
            mut b in proptest::collection::vec(any::<i64>(), 0..64),
        ) {
            a.sort();
            b.sort();
            let got = run(&a, &b);
            prop_assert_eq!(got, sorted_concat(&a, &b));
        }

        #[test]
        fn small_range_duplicates(
            mut a in proptest::collection::vec(-3i64..3, 0..64),
            mut b in proptest::collection::vec(-3i64..3, 0..64),
        ) {
            a.sort();
            b.sort();
            let got = run(&a, &b);
            prop_assert_eq!(got, sorted_concat(&a, &b));
        }
    }
}

/// Sorts `a` in place into non-decreasing order.
///
/// Equal `i64` values are indistinguishable, so an unstable sort yields
/// exactly the same result as a stable one.
pub fn sort(a: &mut [i64]) {
    a.sort_unstable();
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn is_sorted(a: &[i64]) -> bool {
        a.windows(2).all(|w| w[0] <= w[1])
    }

    #[test]
    fn empty() {
        let mut a: [i64; 0] = [];
        sort(&mut a);
        assert_eq!(a, []);
    }

    #[test]
    fn single() {
        let mut a = [42i64];
        sort(&mut a);
        assert_eq!(a, [42]);
    }

    #[test]
    fn basic() {
        let mut a = [3i64, -1, 2, 2, 0, -7, 10];
        sort(&mut a);
        assert_eq!(a, [-7, -1, 0, 2, 2, 3, 10]);
    }

    #[test]
    fn extremes() {
        let mut a = [i64::MAX, 0, i64::MIN, -1, 1, i64::MIN, i64::MAX];
        sort(&mut a);
        assert_eq!(a, [i64::MIN, i64::MIN, -1, 0, 1, i64::MAX, i64::MAX]);
    }

    #[test]
    fn already_sorted_and_reversed() {
        let mut a: Vec<i64> = (0..100).collect();
        sort(&mut a);
        assert!(is_sorted(&a));
        let mut b: Vec<i64> = (0..100).rev().collect();
        sort(&mut b);
        assert_eq!(a, b);
    }

    proptest! {
        #[test]
        fn matches_reference(v in proptest::collection::vec(any::<i64>(), 0..300)) {
            let mut expected = v.clone();
            expected.sort();
            let mut actual = v;
            sort(&mut actual);
            prop_assert_eq!(actual, expected);
        }

        #[test]
        fn small_range_with_duplicates(v in proptest::collection::vec(-5i64..5, 0..300)) {
            let mut expected = v.clone();
            expected.sort();
            let mut actual = v;
            sort(&mut actual);
            prop_assert_eq!(actual, expected);
        }
    }
}

/// Returns `base^exp mod m` in `[0, m)`, computed exactly.
///
/// Expects `base >= 0`, `exp >= 0`, `1 <= m <= 3_000_000_000`.
/// `pow_mod(0, 0, m)` is `1 mod m`.
pub fn pow_mod(base: i64, exp: i64, m: i64) -> i64 {
    let m = m as u128;
    let mut result: u128 = 1 % m;
    let mut b: u128 = (base as u128) % m;
    let mut e: u128 = exp as u128;
    while e > 0 {
        if e & 1 == 1 {
            result = result * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    result as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn reference(base: i64, exp: i64, m: i64) -> i64 {
        // Naive-ish reference using u128 square-and-multiply on the full values.
        let m = m as u128;
        let mut r: u128 = 1 % m;
        let mut b: u128 = base as u128 % m;
        let mut e = exp as u64;
        while e > 0 {
            if e % 2 == 1 {
                r = r * b % m;
            }
            b = b * b % m;
            e /= 2;
        }
        r as i64
    }

    #[test]
    fn basic_values() {
        assert_eq!(pow_mod(2, 10, 1000), 24);
        assert_eq!(pow_mod(3, 4, 5), 1);
        assert_eq!(pow_mod(0, 0, 7), 1);
        assert_eq!(pow_mod(0, 0, 1), 0);
        assert_eq!(pow_mod(5, 0, 1), 0);
        assert_eq!(pow_mod(0, 5, 7), 0);
        assert_eq!(pow_mod(7, 3, 1), 0);
        assert_eq!(pow_mod(i64::MAX, i64::MAX, 3_000_000_000), reference(i64::MAX, i64::MAX, 3_000_000_000));
        assert_eq!(pow_mod(2, i64::MAX, 2), 0);
        assert_eq!(pow_mod(2, i64::MAX, 3), reference(2, i64::MAX, 3));
    }

    #[test]
    fn max_modulus_no_overflow() {
        let m = 3_000_000_000i64;
        assert_eq!(pow_mod(m - 1, 2, m), 1);
        assert_eq!(pow_mod(m - 1, 3, m), m - 1);
        assert_eq!(pow_mod(2_999_999_999, 2_999_999_998, m), reference(2_999_999_999, 2_999_999_998, m));
    }

    proptest! {
        #[test]
        fn matches_reference(base in 0i64..=i64::MAX, exp in 0i64..=i64::MAX, m in 1i64..=3_000_000_000i64) {
            let r = pow_mod(base, exp, m);
            prop_assert!((0..m).contains(&r));
            prop_assert_eq!(r, reference(base, exp, m));
        }

        #[test]
        fn small_exponents_match_naive(base in 0i64..=1_000_000i64, exp in 0u32..40, m in 1i64..=3_000_000_000i64) {
            let mut expected: i128 = 1 % (m as i128);
            for _ in 0..exp {
                expected = expected * (base as i128) % (m as i128);
            }
            prop_assert_eq!(pow_mod(base, exp as i64, m) as i128, expected);
        }
    }
}
